//! Constrained modular arithmetic operations for u128 values.
//!
//! This module provides a `ModU128` struct that implements modular arithmetic operations
//! with full constraint generation for zero-knowledge proof circuits. All operations
//! are verified in-circuit to ensure correctness.
use crate::math::helpers::assert_in_range;
use super::unconstrained_U128::{
    __compute_mod_quotient, __compute_mod_reduction, __div_mod, __inv_mod, __neg,
    __sub_with_underflow,
};

/// Modular arithmetic context for u128 values.
///
/// This struct holds a modulus and provides methods for performing modular arithmetic
/// operations with full constraint generation. All operations are verified in-circuit.
///
/// # Generic Parameters
///
/// The operations work with `Field` values, but are designed for u128-sized integers.
/// The modulus must be a positive value less than 2^128.
pub struct ModU128 {
    /// The modulus for all operations
    pub m: Field,
}

impl ModU128 {
    /// Creates a new modular arithmetic context with the given modulus.
    ///
    /// # Arguments
    /// * `m` - The modulus for all operations. Must be positive.
    ///
    /// # Returns
    /// A new `ModU128` instance configured with the specified modulus.
    pub fn new(m: Field) -> Self {
        ModU128 { m }
    }

    /// Returns the modulus as a Field value.
    ///
    /// # Returns
    /// The modulus value used by this context.
    pub fn get_mod_field(self) -> Field {
        self.m
    }

    /// Reduces a value modulo the modulus.
    ///
    /// Computes `n mod m` and returns the result in the range [0, m).
    /// This operation is fully constrained and verified in-circuit.
    ///
    /// # Arguments
    /// * `n` - The value to reduce
    ///
    /// # Returns
    /// The value `n mod m` in the range [0, m)
    ///
    /// # Panics
    /// The circuit will fail if the reduction is incorrect.
    ///
    /// # Do not use this on a value a prover controls
    /// The quotient below is never bounded, and `n == q * quotient + remainder` is a field equation,
    /// so a prover can pick **any** `remainder` in `[0, m)` and solve for a matching quotient. The
    /// constraint set accepts `(2, 50)` and `((250 - 51) / 100, 51)` alike for `250 mod 100`, which is
    /// the same unbounded-quotient shape as IF-012.
    ///
    /// It is sound where it is used: the only production caller is `bin/config`, which is `fn main()`
    /// with no inputs, so every value it reduces is a compile-time `pub global` and there is no
    /// adversary to choose the second remainder. Use [`reduce_mod_bounded`] for a witness.
    pub fn reduce_mod(self, n: Field) -> Field {
        // Safety: __compute_mod_reduction is safe to call here because we assert the properties of the output
        let (q, r) = unsafe { __compute_mod_reduction(n, self.m) };

        // Ensure remainder is in [0, m)
        assert(r as u128 < self.m as u128);
        // Verify the reduction is correct
        assert(n == q * self.m + r);

        r
    }

    /// Adds two values with modular reduction.
    ///
    /// Computes `(lhs + rhs) mod m` and returns the result.
    /// Handles overflow correctly by reducing modulo the modulus.
    ///
    /// # Arguments
    /// * `lhs` - Left-hand side value
    /// * `rhs` - Right-hand side value
    ///
    /// # Returns
    /// The result of `(lhs + rhs) mod m`
    pub fn add(self, lhs: Field, rhs: Field) -> Field {
        self.reduce_mod(lhs + rhs)
    }

    /// Subtracts two values with modular reduction.
    ///
    /// Computes `(lhs - rhs) mod m` and returns the result.
    /// Handles underflow correctly by adding the modulus when needed.
    ///
    /// # Arguments
    /// * `lhs` - Left-hand side value (minuend)
    /// * `rhs` - Right-hand side value (subtrahend)
    ///
    /// # Returns
    /// The result of `(lhs - rhs) mod m`
    pub fn sub(self, lhs: Field, rhs: Field) -> Field {
        // Safety: __sub_with_underflow is safe because we verify the subtraction equation below
        let (result, underflow) = unsafe { __sub_with_underflow(lhs, rhs, self.m) };

        // Verify the subtraction
        if underflow {
            assert(lhs + self.m == rhs + result, "Subtraction with underflow verification failed");
        } else {
            assert(lhs == rhs + result, "Subtraction verification failed");
        }

        result
    }

    /// Multiplies two values with modular reduction.
    ///
    /// Computes `(lhs * rhs) mod m` and returns the result.
    /// The product is computed first, then reduced modulo the modulus.
    ///
    /// # Arguments
    /// * `lhs` - Left-hand side value
    /// * `rhs` - Right-hand side value
    ///
    /// # Returns
    /// The result of `(lhs * rhs) mod m`
    pub fn mul_mod(self, lhs: Field, rhs: Field) -> Field {
        self.reduce_mod(lhs * rhs)
    }

    /// Computes modular division: `lhs * rhs^(-1) mod m`.
    ///
    /// This is equivalent to multiplying `lhs` by the modular inverse of `rhs`.
    /// The result satisfies: `(result * rhs) mod m = lhs mod m`.
    ///
    /// # Arguments
    /// * `lhs` - The numerator
    /// * `rhs` - The denominator (must be coprime with the modulus)
    ///
    /// # Returns
    /// The result of `(lhs * rhs^(-1)) mod m`
    ///
    /// # Panics
    /// The circuit will fail if `rhs` is not invertible modulo `m` (i.e., if
    /// `gcd(rhs, m) != 1`). For prime moduli, any non-zero `rhs` is invertible.
    pub fn div_mod(self, lhs: Field, rhs: Field) -> Field {
        // Safety: __div_mod is safe because we verify result * rhs = lhs (mod m) below
        let result = unsafe { __div_mod(lhs, rhs, self.m) };

        // Verify: (result * rhs) mod m == lhs mod m
        assert(
            self.mul_mod(result, rhs) == self.reduce_mod(lhs),
            "Division verification failed: result * rhs ≠ lhs (mod m)",
        );

        result
    }

    /// Negates a value modulo m.
    ///
    /// Computes the additive inverse: `(-val) mod m = (m - val) mod m`.
    /// Special case: negation of zero is zero.
    ///
    /// # Arguments
    /// * `val` - The value to negate
    ///
    /// # Returns
    /// The result of `(-val) mod m`, which satisfies `(val + result) mod m = 0`
    pub fn neg(self, val: Field) -> Field {
        // Safety: __neg is safe because we verify val + result = 0 (mod m) below
        let result = unsafe { __neg(val, self.m) };

        // Verify: val + result = 0 (mod m)
        // Special case: if val = 0, result should be 0
        if val == 0 {
            assert(result == 0, "Negation of zero should be zero");
        } else {
            assert(val + result == self.m, "Negation verification failed");
        }

        result
    }

    /// Computes the modular multiplicative inverse using Fermat's Little Theorem.
    ///
    /// For a prime modulus `m` and value `val` coprime to `m`, computes `val^(-1) mod m`
    /// such that `(val * result) mod m = 1`.
    ///
    /// The implementation uses Fermat's Little Theorem: `val^(m-1) = 1 (mod m)`,
    /// so `val^(-1) = val^(m-2) (mod m)`.
    ///
    /// # Arguments
    /// * `val` - The value to invert (must be coprime with the modulus)
    ///
    /// # Returns
    /// The modular inverse `val^(-1) mod m` such that `(val * result) mod m = 1`
    ///
    /// # Panics
    /// The circuit will fail if `val` is not invertible modulo `m` (i.e., if
    /// `gcd(val, m) != 1`). For prime moduli, any non-zero `val` is invertible.
    /// # Do not use this on a value a prover controls
    /// The verification routes through [`ModU128::reduce_mod`], whose remainder is not pinned. Use
    /// [`inv_mod_bounded`] for a witness.
    pub fn inv_mod(self, val: Field) -> Field {
        // Safety: __inv_mod is safe because we verify val * result = 1 (mod m) below
        let result = unsafe { __inv_mod(val, self.m) };

        // Verify: val * result = 1 (mod m)
        assert(self.mul_mod(val, result) == 1, "Inverse verification failed");

        result
    }
}

/// `n mod q` in `[0, q)`, with the quotient **bounded** so the remainder is unique.
///
/// This exists alongside [`ModU128::reduce_mod`] rather than replacing it. That one asserts only
/// `n == q * quotient + remainder` with `remainder < q`; because the equation is over the field and
/// the quotient is unbounded, a prover can pick any `remainder` in `[0, q)` and solve for a matching
/// quotient. That is harmless where it is used — `bin/config` reduces compile-time constants and has
/// no prover-supplied input — but it is not safe for a witness a prover controls.
///
/// Bounding the quotient closes it: with `quotient < 2^BIT_K` and `remainder` in `[0, q)`, the sum
/// `q * quotient + remainder` stays far below the field prime, so the field equation implies the
/// integer one and the pair is the unique Euclidean division.
///
/// `BIT_K` must cover `n / q`, and `n` itself must fit 128 bits for the hint to be correct.
pub fn reduce_mod_bounded<let BIT_Q: u32, let BIT_K: u32>(n: Field, q: Field) -> Field {
    // Safety: the quotient bound and the canonical remainder interval below fix the division, so a
    // wrong hint cannot satisfy both.
    let quotient = unsafe { __compute_mod_quotient(n, q) };
    quotient.assert_max_bit_size::<BIT_K>();
    let remainder = n - q * quotient;
    assert_in_range::<BIT_Q>(remainder, q);
    remainder
}

/// `n mod q` as the **centered** representative in `[-(q-1)/2, (q-1)/2]`, for odd `q`.
///
/// The counterpart to [`reduce_mod_bounded`], which returns the `[0, q)` one. Circuits that hash a
/// polynomial in centered form want this directly: reducing to `[0, q)` and then subtracting `q`
/// behind a comparison computes the same value, but pays for a second representation on the way.
///
/// Same construction as [`reduce_mod_bounded`], shifted by `half`. The quotient is a hint bounded to
/// `BIT_K`, which keeps `q * quotient` and `n` far below the field prime and so makes the
/// subtraction an integer identity rather than a modular one. `assert_in_range` then pins
/// `centered + half` to `[0, q)`. Any `q` consecutive integers contain exactly one representative of
/// each residue class, so that window fixes `centered` uniquely and no other hint satisfies both
/// checks. The quotient bound is therefore about the integer lift, not about which value is picked.
///
/// `q` must be odd, so that `half = (q - 1) / 2` is an integer and the window `[-half, half]` holds
/// exactly `q` values. Every modulus here is an odd prime.
///
/// The caller must keep `n + half < 2^BIT_K * q`, because the quotient divided out is
/// `floor((n + half) / q)` and not `floor(n / q)`. The weaker `n < 2^BIT_K * q` is **not** enough:
/// every `n` in `[2^BIT_K * q - half, 2^BIT_K * q)` satisfies it while the honest quotient is already
/// `2^BIT_K`. If the bound is missed the honest quotient overflows `BIT_K` and the circuit is
/// unsatisfiable — a completeness failure, not a soundness one, since the centered window fixes the
/// result whatever `BIT_K` allows.
///
/// For a sum of `H` canonical residues the condition is slack by a wide margin:
/// `n + half <= (q - 1) * (H + 1/2)`, so the quotient is at most `H`.
pub fn centered_mod_bounded<let BIT_Q: u32, let BIT_K: u32>(n: Field, q: Field) -> Field {
    let half = (q - 1) / 2;
    // Safety: the quotient bound and the canonical centered interval below fix the division, so a
    // wrong hint cannot satisfy both.
    let quotient = unsafe { __compute_mod_quotient(n + half, q) };
    quotient.assert_max_bit_size::<BIT_K>();
    let centered = n - q * quotient;
    assert_in_range::<BIT_Q>(centered + half, q);
    centered
}

/// The inverse of `a` modulo prime `q`, proven by `a * inverse == 1 (mod q)`.
///
/// Uses [`reduce_mod_bounded`] for the verification, so unlike [`ModU128::inv_mod`] the reduction
/// behind the check pins its remainder. `a` is reduced first to keep the product under 128 bits.
pub fn inv_mod_bounded<let BIT_Q: u32, let BIT_K: u32>(a: Field, q: Field) -> Field {
    // Safety: the range check and the product below pin the inverse.
    let inverse = unsafe { __inv_mod(a, q) };
    assert_in_range::<BIT_Q>(inverse, q);
    a.assert_max_bit_size::<128>();
    let reduced = reduce_mod_bounded::<BIT_Q, BIT_K>(a, q);
    assert(
        reduce_mod_bounded::<BIT_Q, BIT_K>(reduced * inverse, q) == 1,
        "modular inverse mismatch",
    );
    inverse
}

#[test]
fn test_reduce_mod_already_reduced() {
    let value = 42;
    let m = ModU128::new(100);
    let result = m.reduce_mod(value);
    assert(result == 42);
}

#[test]
fn test_reduce_mod_needs_reduction() {
    let value = 250;
    let m = ModU128::new(100);
    let result = m.reduce_mod(value);
    assert(result == 50);
}

#[test]
fn test_reduce_mod_exact_multiple() {
    let value = 300;
    let m = ModU128::new(100);
    let result = m.reduce_mod(value);
    assert(result == 0);
}

#[test]
fn test_reduce_mod_large_value() {
    let value = 123456789;
    let m = ModU128::new(1000);
    let result = m.reduce_mod(value);
    assert(result == 789);
}

#[test]
fn test_add_no_overflow() {
    let a = 30;
    let b = 40;
    let m = ModU128::new(100);
    let result = m.add(a, b);
    assert(result == 70);
}

#[test]
fn test_add_with_overflow() {
    let a = 60;
    let b = 50;
    let m = ModU128::new(100);
    let result = m.add(a, b);
    assert(result == 10); // (60 + 50) mod 100 = 10
}

#[test]
fn test_add_exact_modulus() {
    let a = 50;
    let b = 50;
    let m = ModU128::new(100);
    let result = m.add(a, b);
    assert(result == 0);
}

#[test]
fn test_add_with_zero() {
    let a = 42;
    let b = 0;
    let m = ModU128::new(100);
    let result = m.add(a, b);
    assert(result == 42);
}

#[test]
fn test_sub_no_underflow() {
    let a = 50;
    let b = 30;
    let m = ModU128::new(100);
    let result = m.sub(a, b);
    assert(result == 20);
}

#[test]
fn test_sub_with_underflow() {
    let a = 30;
    let b = 50;
    let m = ModU128::new(100);
    let result = m.sub(a, b);
    assert(result == 80); // (30 - 50 + 100) mod 100 = 80
}

#[test]
fn test_sub_equal_values() {
    let a = 42;
    let b = 42;
    let m = ModU128::new(100);
    let result = m.sub(a, b);
    assert(result == 0);
}

#[test]
fn test_sub_subtract_zero() {
    let a = 42;
    let b = 0;
    let m = ModU128::new(100);
    let result = m.sub(a, b);
    assert(result == 42);
}
#[test]
fn test_mul_mod_small_values() {
    let a = 6;
    let b = 7;
    let m = ModU128::new(100);
    let result = m.mul_mod(a, b);
    assert(result == 42);
}

#[test]
fn test_mul_mod_with_reduction() {
    let a = 12;
    let b = 15;
    let m = ModU128::new(100);
    let result = m.mul_mod(a, b);
    assert(result == 80); // 12 * 15 = 180, 180 mod 100 = 80
}

#[test]
fn test_mul_mod_result_zero() {
    let a = 5;
    let b = 20;
    let m = ModU128::new(100);
    let result = m.mul_mod(a, b);
    assert(result == 0); // 5 * 20 = 100, 100 mod 100 = 0
}

#[test]
fn test_mul_mod_with_zero() {
    let a = 42;
    let b = 0;
    let m = ModU128::new(100);
    let result = m.mul_mod(a, b);
    assert(result == 0);
}

#[test]
fn test_mul_mod_large_values() {
    let a = 123;
    let b = 456;
    let m = ModU128::new(1000);
    let result = m.mul_mod(a, b);
    assert(result == 88); // 123 * 456 = 56088, 56088 mod 1000 = 88
}

#[test]
fn test_neg_non_zero() {
    let val = 30;
    let m = ModU128::new(100);
    let result = m.neg(val);
    assert(result == 70); // 100 - 30 = 70
}

#[test]
fn test_neg_zero() {
    let val = 0;
    let m = ModU128::new(100);
    let result = m.neg(val);
    assert(result == 0); // Negation of 0 is 0, not m
}

#[test]
fn test_neg_large_modulus() {
    let val = 12345;
    let m = ModU128::new(1000000);
    let result = m.neg(val);
    assert(result == 987655); // 1000000 - 12345 = 987655
}

#[test]
fn test_inv_mod_simple() {
    let val = 3;
    let m = ModU128::new(11);
    let result = m.inv_mod(val);
    // 3 * 4 = 12 = 1 (mod 11), so 3^(-1) = 4 (mod 11)
    assert(result == 4);
    // Verify: 3 * result = 1 (mod 11)
    assert(m.mul_mod(val, result) == 1);
}

#[test]
fn test_inv_mod_larger_prime() {
    let val = 7;
    let m = ModU128::new(13);
    let result = m.inv_mod(val);
    // Verify: 7 * result = 1 (mod 13)
    assert(m.mul_mod(val, result) == 1);
}

#[test]
fn test_inv_mod_with_result_verification() {
    let val = 5;
    let m = ModU128::new(17);
    let result = m.inv_mod(val);
    // Verify the inverse property
    let product = m.mul_mod(val, result);
    assert(product == 1);
}

#[test]
fn test_inv_mod_coprime_values() {
    let val = 9;
    let m = ModU128::new(23);
    let result = m.inv_mod(val);
    assert(m.mul_mod(val, result) == 1);
}

#[test]
fn test_div_mod_simple() {
    let a = 6;
    let b = 2;
    let m = ModU128::new(11);
    let result = m.div_mod(a, b);
    assert(result == 3); // 6 / 2 = 3
}

#[test]
fn test_div_mod_with_inverse() {
    let a = 7;
    let b = 3;
    let m = ModU128::new(11);
    let result = m.div_mod(a, b);
    // 3^(-1) mod 11 = 4 (since 3 * 4 = 12 = 1 mod 11)
    // 7 * 4 = 28 = 6 (mod 11)
    assert(result == 6);
    // Verify: result * b = a (mod m)
    assert(m.mul_mod(result, b) == a);
}

#[test]
fn test_div_mod_verification() {
    let a = 10;
    let b = 3;
    let m = ModU128::new(17);
    let result = m.div_mod(a, b);
    // Verify: result * b = a (mod m)
    assert(m.mul_mod(result, b) == m.reduce_mod(a));
}

#[test]
fn test_div_mod_larger_values() {
    let a = 250;
    let b = 7;
    let m = ModU128::new(97);
    let result = m.div_mod(a, b);
    // Verify: result * b = a (mod m)
    let a_reduced = m.reduce_mod(a); // 250 mod 100 = 50
    assert(m.mul_mod(result, b) == a_reduced);
}

#[test]
fn test_reduce_mod_function() {
    let m = ModU128::new(7);

    // Test reduce_mod directly first
    assert(m.reduce_mod(38) == 3);
    assert(m.reduce_mod(6) == 6);
    assert(m.reduce_mod(7) == 0);
    assert(m.reduce_mod(14) == 0);
}

#[test]
fn test_field_properties_multiplicative_identity() {
    let a = 42;
    let m = ModU128::new(100);
    // a * 1 = a
    assert(m.mul_mod(a, 1) == a);
}

#[test]
fn test_field_properties_additive_inverse() {
    let a = 42;
    let m = ModU128::new(100);
    let neg_a = m.sub(0, a);
    // a + (-a) = 0
    assert(m.add(a, neg_a) == 0);
}

#[test]
fn test_field_properties_commutativity_add() {
    let a = 35;
    let b = 47;
    let m = ModU128::new(100);
    // a + b = b + a
    assert(m.add(a, b) == m.add(b, a));
}

#[test]
fn test_field_properties_commutativity_mul() {
    let a = 7;
    let b = 9;
    let m = ModU128::new(100);
    // a * b = b * a
    assert(m.mul_mod(a, b) == m.mul_mod(b, a));
}

#[test]
fn test_field_properties_associativity_add() {
    let a = 23;
    let b = 34;
    let c = 45;
    let m = ModU128::new(100);
    // (a + b) + c = a + (b + c)
    let left = m.add(m.add(a, b), c);
    let right = m.add(a, m.add(b, c));
    assert(left == right);
}

#[test]
fn test_field_properties_associativity_mul() {
    let a = 3;
    let b = 7;
    let c = 11;
    let m = ModU128::new(100);
    // (a * b) * c = a * (b * c)
    let left = m.mul_mod(m.mul_mod(a, b), c);
    let right = m.mul_mod(a, m.mul_mod(b, c));
    assert(left == right);
}

#[test]
fn test_field_properties_distributivity() {
    let a = 5;
    let b = 7;
    let c = 9;
    let m = ModU128::new(100);
    // a * (b + c) = (a * b) + (a * c)
    let left = m.mul_mod(a, m.add(b, c));
    let right = m.add(m.mul_mod(a, b), m.mul_mod(a, c));
    assert(left == right);
}
#[test]
fn test_division_multiplication_inverse() {
    let a = 35;
    let b = 7;
    let m = ModU128::new(97);
    let quotient = m.div_mod(a, b);
    let product = m.mul_mod(quotient, b);
    assert(product == m.reduce_mod(a));
}

#[test]
fn test_inverse_of_inverse() {
    let a = 7;
    let m = ModU128::new(11);
    // (a^(-1))^(-1) = a
    let inv_a = m.inv_mod(a);
    let inv_inv_a = m.inv_mod(inv_a);
    assert(inv_inv_a == a);
}

#[test]
fn test_operations_with_prime_modulus() {
    let m = ModU128::new(97); // Prime number
    let a = 42;
    let b = 13;

    // Test addition
    let sum = m.add(a, b);
    assert(sum == 55); // 42 + 13 = 55

    // Test subtraction
    let diff = m.sub(a, b);
    assert(diff == 29); // 42 - 13 = 29

    // Test multiplication
    let prod = m.mul_mod(a, b);
    assert(prod == 61); // (42 * 13) mod 97 = 546 mod 97 = 61

    // Test inverse: b * b^(-1) = 1 (mod m)
    let inv = m.inv_mod(b);
    assert(m.mul_mod(b, inv) == 1);

    // Test division: (a / b) * b = a (mod m)
    let quot = m.div_mod(a, b);
    assert(m.mul_mod(quot, b) == a);
}

/// `centered_mod_bounded` at every boundary of the window, for `q = 101` (`half = 50`).
///
/// The interesting pairs are `half` / `half + 1`, where the representative flips sign, and `q - 1` /
/// `q`, where it wraps. Off-by-one in either direction shows up here.
#[test]
fn test_centered_mod_bounded_window_boundaries() {
    let q = 101;
    // Below the flip, at it, and one past it.
    assert(centered_mod_bounded::<7, 4>(0, q) == 0);
    assert(centered_mod_bounded::<7, 4>(49, q) == 49);
    assert(centered_mod_bounded::<7, 4>(50, q) == 50);
    assert(centered_mod_bounded::<7, 4>(51, q) == -50);
    // Top of the first period, then the wrap.
    assert(centered_mod_bounded::<7, 4>(100, q) == -1);
    assert(centered_mod_bounded::<7, 4>(101, q) == 0);
    assert(centered_mod_bounded::<7, 4>(151, q) == 50);
    assert(centered_mod_bounded::<7, 4>(152, q) == -50);
}

/// The C4 case: a sum of `H` residues, each in `[0, q)`, at the largest value it can take.
///
/// With `H = 14` and `q = 101` the sum tops out at `14 * 100 = 1400`, and the carry is exactly 14 —
/// the worst case the `BIT_K` bound has to cover for the `small` committee.
#[test]
fn test_centered_mod_bounded_covers_full_aggregate() {
    let q = 101;
    let n = 14 * (q - 1);
    // 1400 = 13 * 101 + 87, and 87 > 50, so the representative is 87 - 101.
    assert(centered_mod_bounded::<7, 4>(n, q) == -14);
    // The carry is floor((1400 + 50) / 101) = 14, which needs all four bits.
    assert(centered_mod_bounded::<7, 5>(n, q) == -14);
}

/// The exact `BIT_K` threshold, which sits `half` below the naive one.
///
/// The quotient is `floor((n + half) / q)`, so the largest provable `n` is `2^BIT_K * q - half - 1`,
/// not `2^BIT_K * q - 1`. With `q = 101`, `half = 50` and `BIT_K = 4` that is 1565: one more and the
/// honest quotient is 16, which four bits cannot hold. The window between the two -- 1566 to 1615 --
/// is exactly what a precondition written as `n < 2^BIT_K * q` would wrongly admit.
#[test]
fn test_centered_mod_bounded_carry_threshold_accounts_for_half() {
    let q = 101;
    // 1565 + 50 = 1615 = 15 * 101 + 100, so the carry is 15 and fits four bits.
    // 1565 mod 101 is 50, exactly `half`, so the representative stays positive.
    assert(centered_mod_bounded::<7, 4>(1565, q) == 50);
    // One more: 1566 + 50 = 1616 = 16 * 101 exactly, so the carry is 16 and needs five bits.
    // 1566 mod 101 is 51, one past `half`, so the representative flips to 51 - 101.
    assert(centered_mod_bounded::<7, 5>(1566, q) == -50);
}

/// The first value the stricter precondition excludes must actually be unprovable.
#[test(should_fail)]
fn test_centered_mod_bounded_rejects_carry_just_past_threshold() {
    // 1566 is below 2^4 * 101 = 1616, yet its carry is 16 -- the case the loose bound would allow.
    let _ = centered_mod_bounded::<7, 4>(1566, 101);
}

/// A carry that does not fit `BIT_K` makes the circuit unsatisfiable rather than wrong.
///
/// This is the failure mode if a committee grows past the bound `execute` asserts: the honest
/// prover cannot prove, which is the safe direction.
#[test(should_fail)]
fn test_centered_mod_bounded_rejects_overflowing_carry() {
    let q = 101;
    // Carry is 14; two bits hold at most 3.
    let _ = centered_mod_bounded::<7, 2>(14 * (q - 1), q);
}

/// Centered and canonical reduction must describe the same residue class.
///
/// `centered_mod_bounded` replaced a `reduce_mod` followed by a conditional subtraction, so this
/// pins the relationship that replacement relies on.
#[test]
fn test_centered_mod_bounded_agrees_with_reduce_mod_bounded() {
    let q = 101;
    let half = (q - 1) / 2;
    for n in 0..303 {
        let centered = centered_mod_bounded::<7, 4>(n as Field, q);
        let reduced = reduce_mod_bounded::<7, 4>(n as Field, q);
        let expected = if (reduced as u64) > (half as u64) {
            reduced - q
        } else {
            reduced
        };
        assert(centered == expected);
    }
}

