    // Test that both consecutive ABSORB and SQUEEZE operations are properly aggregated
    // Pattern: ABSORB(1), ABSORB(1), SQUEEZE(1), SQUEEZE(1), ABSORB(1)
    // Should aggregate to: ABSORB(2), SQUEEZE(2), ABSORB(1)
